(()=>{'use strict';
const D=window.TOPIC_LIBRARY,$=s=>document.querySelector(s),G=new Map(D.games.map(g=>[g.id,g])),T=new Map(D.templates.map(t=>[t.id,t]));
const labels={high:'高 · 优先尝试',medium:'中 · 有条件尝试',low:'低 · 暂缓',unknown:'待核验',not_applicable:'非目标'};
const scopes={eligible:'独立对抗',pending:'待核验模式',excluded:'非目标模式',all:'全部已解构',catalog:'全部候选'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=v=>{try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
const name=g=>g.displayName||g.name,rank={high:0,medium:1,low:2,unknown:3,not_applicable:4};
let state={},page=1,expanded=false;
const fields=['scope','platform','level','q','template','game','mode'];
function readState(){let h=location.hash.slice(1).split('?');let p=new URLSearchParams(h[1]||'');state={route:h[0]||'library',scope:p.get('scope')||'eligible'};for(let k of fields)if(p.has(k))state[k]=p.get(k);}
function url(changes={}){let s={...state,...changes},p=new URLSearchParams();for(let k of fields)if(s[k]&&!(k==='scope'&&s[k]==='eligible'))p.set(k,s[k]);return '#'+(s.route||'library')+(p.size?'?'+p:'');}
function go(changes){page=1;let u=url(changes);if(location.hash===u)render();else location.hash=u;}
function badge(m){let a=m.npcSuitability;return `<span class="badge ${esc(a.level)}">${esc(labels[a.level])}</span>`;}
function matches(m,ignoreTemplate=false){let g=G.get(m.gameId);if(state.platform&&g.platform!==state.platform)return false;if(state.level&&m.npcSuitability.level!==state.level)return false;if(state.scope!=='all'&&state.scope!=='catalog'&&m.scope!==state.scope)return false;if(!ignoreTemplate&&state.template&&m.templateId!==state.template)return false;let q=(state.q||'').toLowerCase();return !q||[name(g),g.name,m.name,m.summary,m.actions,m.rules,T.get(m.templateId)?.name,m.npcSuitability.reason,m.npcSuitability.npcTasks].join(' ').toLowerCase().includes(q);}
function results(ignoreTemplate=false){return Object.values(D.modes).filter(m=>matches(m,ignoreTemplate)).sort((a,b)=>rank[a.npcSuitability.level]-rank[b.npcSuitability.level]||name(G.get(a.gameId)).localeCompare(name(G.get(b.gameId))));}
function catalog(){return D.games.filter(g=>{if(state.platform&&g.platform!==state.platform)return false;if(g.modes.length)return g.modes.some(id=>matches(D.modes[id]));if(state.level||state.template)return false;return !state.q||[name(g),g.name,g.description].join(' ').toLowerCase().includes(state.q.toLowerCase());});}
function bind(root){root.querySelectorAll('[data-template]').forEach(el=>el.onclick=()=>go({template:el.dataset.template,game:'',mode:'',route:'library',scope:state.scope==='catalog'?'all':state.scope}));root.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{let m=D.modes[el.dataset.mode];go({game:m.gameId,mode:m.id,route:'library'});});root.querySelectorAll('[data-game]').forEach(el=>el.onclick=()=>go({game:el.dataset.game,mode:'',route:'library'}));root.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>go({scope:el.dataset.scope,template:'',level:'',game:'',mode:'',route:'library'}));root.querySelectorAll('[data-back]').forEach(el=>el.onclick=()=>go({game:'',mode:'',route:'library'}));root.querySelectorAll('img').forEach(im=>im.onerror=()=>{im.hidden=true;});}
function tree(){let ms=results(true);$('#tree').innerHTML=D.categories.map(c=>{let ts=D.templates.filter(t=>t.category===c.id&&ms.some(m=>m.templateId===t.id));if(!ts.length)return '';return `<details class="category" ${expanded||state.template&&ts.some(t=>t.id===state.template)?'open':''}><summary>${esc(c.name)}<span>${ts.reduce((n,t)=>n+ms.filter(m=>m.templateId===t.id).length,0)}</span></summary>${ts.map(t=>{let ls=ms.filter(m=>m.templateId===t.id);return `<details class="template" ${expanded||state.template===t.id?'open':''}><summary><button data-template="${t.id}" class="${state.template===t.id?'active':''}">${esc(t.name)}</button><span>${ls.length}</span></summary>${ls.map(m=>`<button class="leaf ${state.mode===m.id?'active':''}" data-mode="${esc(m.id)}">${esc(name(G.get(m.gameId)))}<small>${m.platform==='steam'?'Steam':'Roblox'} · ${esc(labels[m.npcSuitability.level])}</small></button>`).join('')}</details>`;}).join('')}</details>`;}).join('')||'<p class="muted empty-tree">当前条件没有模板。未解构候选可在右侧目录浏览。</p>';bind($('#tree'));$('#expand').textContent=expanded?'全部收起':'全部展开';}
function cover(g){return `<div class="cover ${g.platform}">${g.icon?`<img loading="lazy" src="${safe(g.icon)}" alt="" referrerpolicy="no-referrer">`:''}<span class="platform">${g.platform==='steam'?'Steam':'Roblox'}</span></div>`;}
function card(m){let g=G.get(m.gameId);return `<button class="game-card" data-mode="${esc(m.id)}">${cover(g)}<div class="card-body"><div class="card-top">${badge(m)}<span>${esc(T.get(m.templateId)?.name)}</span></div><h3>${esc(name(g))}</h3><p class="mode-name">${esc(m.name)}</p><p class="summary">${esc(/[\u4e00-\u9fff]/.test(m.summary)?m.summary:m.rules)}</p><div class="npc-line"><b>NPC 判断</b><p>${esc(m.npcSuitability.reason)}</p></div></div><div class="card-foot">查看玩法与适配依据 <span>↗</span></div></button>`;}
function list(){let ms=results(),isCatalog=state.scope==='catalog',records=isCatalog?catalog():ms,n=records.length,per=24;page=Math.min(page,Math.max(1,Math.ceil(n/per)));let t=T.get(state.template),stats=D.meta.scopeCounts;
return `<section class="heading"><div><p class="eyebrow">${state.platform?state.platform.toUpperCase():'STEAM + ROBLOX'} / TOPIC LIBRARY</p><h2>${t?esc(t.name):esc(scopes[state.scope]||'独立对抗')}</h2><p>${t?esc(t.description):'从原作规则出发，判断什么玩法值得改成一个人的竞技体验。'}</p></div><button class="secondary" id="export-results">导出当前结果</button></section><div class="metrics"><button data-scope="eligible" class="${state.scope==='eligible'?'chosen':''}"><span>可进入选题</span><strong>${stats.eligible.games}</strong><small>${stats.eligible.modes} 个已评级模式</small></button><button data-scope="pending" class="${state.scope==='pending'?'chosen':''}"><span>模式待核验</span><strong>${stats.pending.games}</strong><small>先补范围和规则</small></button><button data-scope="excluded" class="${state.scope==='excluded'?'chosen':''}"><span>非目标资料</span><strong>${stats.excluded.games}</strong><small>合作、组队等已归档</small></button><button data-scope="all"><span>已解构总量</span><strong>${D.meta.analysisCount.toLocaleString()}</strong><small>Steam 500 · Roblox 1,030</small></button></div><div class="notice"><span>筛选口径</span>玩家独立完成体验，对手由 NPC 控制。适配度是设计判断，未做趣味性测试；不同模式分别统计。</div>${t?`<div class="template-note"><b>共同规则</b><p>${esc(t.description)}</p><b>NPC 的任务</b><p>${esc(t.npcTask)}</p></div>`:''}<div class="result-line"><p><b>${isCatalog?n:new Set(ms.map(m=>m.gameId)).size}</b> 款游戏${isCatalog?'':` · ${n} 个模式`}${state.q?` · 搜索「${esc(state.q)}」`:''}</p><span>适配度优先 · ${page} / ${Math.max(1,Math.ceil(n/per))} 页</span></div>${n?`<div class="cards">${records.slice((page-1)*per,page*per).map(x=>isCatalog?`<button class="catalog-row" data-game="${esc(x.id)}"><span class="platform-text">${x.platform==='steam'?'Steam':'Roblox'}</span><h3>${esc(name(x))}</h3><p>${x.modes.length?x.modes.length+' 个已记录模式':'仅候选 · 尚未解构'}</p></button>`:card(x)).join('')}</div>`:'<div class="empty"><h3>没有匹配的选题</h3><p>试试其他平台或适配度，或清除左侧筛选。</p></div>'}<div class="pagination"><button id="prev" ${page<=1?'disabled':''}>上一页</button><span>${n?((page-1)*per+1)+'–'+Math.min(page*per,n):'0'} / ${n}</span><button id="next" ${page*per>=n?'disabled':''}>下一页</button></div>`;}
function refs(m,k){return (m.evidence?.[k]||[]).map(id=>{let i=m.sources.findIndex(s=>s.id===id);return i<0?'':`<a class="ref" href="#source-${esc(id)}" data-source="${esc(id)}">[${i+1}]</a>`;}).join('');}
function detail(){let g=G.get(state.game);if(!g)return '<div class="empty">记录不存在。<button data-back>返回选题</button></div>';let choices=g.modes.map(id=>D.modes[id]),m=choices.find(m=>m.id===state.mode)||choices.find(matches)||choices[0];return `<button class="back" data-back>← 返回选题</button><div class="detail-heading"><div><span class="platform-text">${g.platform==='steam'?'Steam':'Roblox'}</span><h2>${esc(name(g))}</h2></div><div class="actions"><a class="primary" href="${safe(g.url)}" target="_blank" rel="noopener noreferrer">打开原作 ↗</a><button id="export-one" class="secondary">导出简表</button></div></div>${!m?`<section class="panel"><h3>候选 · 尚未解构</h3><p>已保留原始目录记录。没有充分的模式规则前，不进入独立对抗选题。</p><p>${esc(g.description)}</p></section>`:`<div class="mode-tabs">${choices.map(x=>`<button class="${x.id===m.id?'selected':''}" data-mode="${esc(x.id)}">${esc(x.name)}</button>`).join('')}</div><div class="detail-meta">${badge(m)}<span>${esc(scopes[m.scope])}</span><span>${esc(m.playerCountNote||'人数按当前模式记录')}</span></div><section class="intro"><p class="eyebrow">原作事实 / ${esc(m.name)}</p><p>${esc(m.summary)}${refs(m,'summary')}</p></section><div class="detail-columns"><div><h3 class="section-title">玩法怎样发生</h3><div class="mechanics">${[['controls','01','怎么操作'],['actions','02','做了什么'],['rules','03','触发什么'],['result','04','如何得结果']].map(([k,no,n])=>`<section class="step"><span>${no}</span><div><h4>${n}${refs(m,k)}</h4><p>${esc(m[k])}</p></div></section>`).join('')}</div><section class="panel"><h3>玩家怎样相互影响${refs(m,'multiplayer')}</h3><p>${esc(m.multiplayer)}</p>${m.impact?`<p>${esc(m.impact)}${refs(m,'impact')}</p>`:''}${m.information?`<h4>信息与角色</h4><p>${esc(m.information)}${refs(m,'information')}</p>`:''}</section></div><div><section class="npc-panel"><p class="eyebrow">NPC OPPONENT / 设计判断</p><h3>对手适配度 ${badge(m)}</h3><p>${esc(m.npcSuitability.reason)}</p>${[['npcTasks','NPC 需要做什么'],['risks','主要难点'],['prototype','建议先验证']].map(([k,n])=>`<h4>${n}</h4><p>${esc(m.npcSuitability[k])}</p>`).join('')}<p class="assessment-note">${m.npcSuitability.reviewMethod==='mode_text_review'?'逐卡文本复核':m.npcSuitability.reviewMethod==='tag_screen'?'按已有关系标签初筛':'文本规则初筛，仍需人工复核'} · 未做 NPC 原型测试。原作原生机器人能力未在此统一核验。</p></section><section class="panel variants"><h3>已有变体想法</h3><p class="muted">以下是设计方案，不是原作规则。</p><ul>${m.variants.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section></div></div><section class="panel"><h3>统一模板与原始归属</h3><button class="template-chip" data-template="${m.templateId}">${esc(T.get(m.templateId)?.name)} →</button>${m.originalTemplates.map(t=>`<p><b>${esc(t.name)}</b> · ${esc(t.scope)}</p>`).join('')}</section><section class="panel sources"><h3>原作资料与核验状态</h3>${m.sources.map((s,i)=>`<article id="source-${esc(s.id)}"><span class="source-num">${i+1}</span><div><a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.excerpt)}</p><small>${esc(s.accessedAt?.slice(0,10))} · ${s.verification==='video_observed'?'实机片段已核验':s.verification==='text_read'?'文本已读':'仅链接 · 未观看或读取'}</small></div></article>`).join('')}</section>${m.unknowns?.length?`<section class="panel"><h3>仍需核验</h3><ul>${m.unknowns.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>`:''}`}`;}
function method(){return `<section class="heading"><div><p class="eyebrow">RESEARCH NOTES</p><h2>同一套标准，两份资料库</h2><p>保留原作事实，把改编判断放在单独一层。</p></div></section><section class="panel"><h3>什么进入独立对抗选题</h3><p>玩家不需要人类队友，能自己完成体验；对手有可表达的行为，并通过规则影响玩家的处境、资源、选择或结果。NPC 替换是改编方向，不意味着原作自带机器人。</p><p>合作与人类组队归入非目标。混合模式、资料不足或未逐卡确认的记录保留待核验。一人控制多个虚拟单位不自动视作人类组队。</p></section><section class="panel"><h3>这次整合了什么</h3><p>Steam 500 款已解构游戏、522 个模式；Roblox 1,030 款已解构游戏。连同未解构的候选，共保留 ${D.meta.catalogCount.toLocaleString()} 条跨平台游戏记录。</p><p>Steam 沿用已有逐模式评级。Roblox 本次逐卡评估了 20 个个人对抗玩法；其余只做明确标注的文本初筛，未确认的不会自动获得适配分数。当前共有 ${D.meta.scopeCounts.eligible.games} 款、${D.meta.scopeCounts.eligible.modes} 个模式进入选题。</p><p>游戏可以有多个模式，分组游戏数可能重叠；目录规模不是平台游戏总数。Roblox 服务器人数没有当作模式人数。</p></section><section class="panel"><h3>适配度怎样用</h3><dl class="rubric"><dt>高 · 优先尝试</dt><dd>短循环、少量明确行为，先验证有限规则的 NPC 原型。</dd><dt>中 · 有条件尝试</dt><dd>存在明确竞争，但动作、寻路、信息或策略需要专门处理。</dd><dt>低 · 暂缓</dt><dd>完整体验依赖复杂长期策略或社交表达，不适合直接做轻量复刻。</dd><dt>待核验</dt><dd>模式或依据不够清楚，不能作为低分处理。</dd></dl><p>纯粹比成绩可能更适合影子挑战，应先确认是否有必要制作独立 NPC 行为。适配度不等于趣味性、真人感或 Feed 适配度。</p></section><section class="panel"><h3>可追溯、可更新</h3><p>按平台和原始标识区分游戏；每个模式保留来源、原始模板、解构字段和改编想法。网站和导出使用同一份资料。刷新本地资料后重新生成即可同步更新。</p></section>`;}
function download(value,filename){let u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#toast').textContent='已导出资料';$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),1800);}
function render(){readState();for(let k of ['scope','platform','level'])$('#'+k).value=state[k]||'';$('#search').value=state.q||'';$('#coverage').innerHTML=`已解构 <b>${D.meta.analysisCount.toLocaleString()}</b> 款<br>资料快照 · ${D.meta.builtAt.slice(0,10)}<br><a href="#method">查看范围与评级口径</a>`;tree();$('#main').innerHTML=state.route==='method'?method():state.game?detail():list();bind($('#main'));$('#prev')?.addEventListener('click',()=>{page--;render();$('#main').scrollTop=0;});$('#next')?.addEventListener('click',()=>{page++;render();$('#main').scrollTop=0;});$('#export-results')?.addEventListener('click',()=>download({meta:D.meta,filters:state,records:state.scope==='catalog'?catalog():results(),games:state.scope==='catalog'?undefined:[...new Set(results().map(m=>m.gameId))].map(id=>G.get(id))},'riffle-filtered.json'));$('#export-one')?.addEventListener('click',()=>{let g=G.get(state.game);download({game:g,modes:g.modes.map(id=>D.modes[id])},'riffle-'+g.id.replaceAll(':','-')+'.json');});$('#main').querySelectorAll('[data-source]').forEach(el=>el.onclick=e=>{e.preventDefault();document.getElementById('source-'+el.dataset.source)?.scrollIntoView({behavior:'smooth',block:'center'});});document.title=(state.game&&G.has(state.game)?name(G.get(state.game))+' · ':'')+'Riffle 独立对抗选题库';}
$('#export-all').onclick=()=>download(D,'riffle-duel-library.json');$('#reset').onclick=()=>{page=1;location.hash='#library';if(!location.hash.includes('?'))render();};$('#expand').onclick=()=>{expanded=!expanded;tree();};for(let k of ['platform','level','scope'])$('#'+k).onchange=e=>go({[k]:e.target.value,game:'',mode:'',template:k==='scope'?'':state.template,route:'library'});let timer;$('#search').oninput=e=>{clearTimeout(timer);const value=e.target.value;timer=setTimeout(()=>go({q:value,game:'',mode:'',route:'library'}),180);};window.addEventListener('hashchange',()=>{render();$('#main').scrollTop=0;});render();
})();
